INSERT INTO author (id, name) VALUES (0, 'J.R.R. Tolkien');
INSERT INTO author (id, name) VALUES (1, 'Frank Herbert');
INSERT INTO book (name, author_id, release_date, description) VALUES ('Ringens brödraskap', 0, '2019-08-29', '"En ring att styra dem, en ring att se dem, en ring att fånga dem och till mörkret ge dem, i Mordor, i skuggornas land" Hobbiten Frodo har fått ta över den magiska ring hans farbror Bilbo en gång vann av Gollum. Gandalf grå inser att det är den stora ring som en gång smiddes av den onde Sauron och som styr alla andra maktens ringar. Tillsammans med följerslagarna Sam, Merry och Pippin ger sig Frodo ut på en lång färd för att förgöra ringen i Eldsberget i Mordor.');
INSERT INTO book (name, author_id, release_date, description) VALUES ('De två tornen', 0, '2019-08-29', 'Hobbiten Frodo har fått ta över den magiska ring hans farbror Bilbo en gång vann av Gollum. Gandalf grå inser att det är den stora ringen som en gång smiddes av den onde Sauron och som styr alla andra maktens ringar. Tillsammans med följerslagarna Sam, Merry och Pippin ger sig Frodo ut på en lång färd för att förgöra ringen i Eldsberget i Mordor. Annars kan ondskan snart komma att härska över Midgård.');
INSERT INTO book (name, author_id, release_date, description) VALUES ('Konungens återkomst', 0, '2019-08-29', 'Hobbiten Frodo har fått ta över den magiska ring hans farbror Bilbo en gång vann av Gollum. Gandalf grå inser att det är den stora ringen som en gång smiddes av den onde Sauron och som styr alla andra maktens ringar. Tillsammans med följerslagarna Sam, Merry och Pippin ger sig Frodo ut på en lång färd för att förgöra ringen i Eldsberget i Mordor. Annars kan ondskan snart komma att härska över Midgård.');
INSERT INTO book (name, author_id, release_date, description) VALUES ('Dune', 1, '2019-06-01', 'I centrum för maktkampen inom ett bysantinskt rymdimperium ligger planeten Arrakis, vindsvept och uttorkad men oändligt värdefull på grund av den sällsynta Kryddan: en substans som skänker psykiska krafter och gör det möjligt att navigera mellan stjärnorna. Till Arrakis kommer adelssläkten Atreides, av kejsaren utsedd att överta kryddutvinningen från det mäktigare huset Harkonnen. Snart utbryter ett krig mellan de två husen. Harkonnens tycks förutbestämda att vinna då en tredje grupp äntrar scenen - Arrakis urinvånare som i den unge hertigen Paul Atreides tycker sig se en länge väntad messias.');
INSERT INTO book (name, author_id, release_date, description) VALUES ('Dune Messiah', 1, '2019-06-01', 'Paul Atreides, även kallad MuadDib, är härskare över tusen planeter, den store segraren i det heliga kriget, prinsen som blev revolutionsledare och ett fanatiskt, religiöst systerskaps Messias. Men nu riskerar han att fällas av just de krafter som skapade honom. Trots att han förutser sina fienders planer är han fast besluten att fortsätta på vägen mot sin egen, chockerande annorlunda, vision om framtiden.');
INSERT INTO book (name, author_id, release_date, description) VALUES ('Children of Dune', 1, '2019-06-01', 'Ökenplaneten Arrakis grönskar. Den har blivit vattenrik och fertil. Den gamle Paul Atreides, som ledde ökenfolket Fremen till politisk och religiös dominans över galaxen, är borta. Men för Dune betyder planetens blomstring även fröet till dess undergång. Det ändrade klimatet utrotar de gigantiska sandmaskarna, vilket i sin tur är en katastrof för planetens ekonomi. Leto och Ghanima, Paul Atreides tvillingbarn och hans arvingar, kan se flera möjliga lösningar - men fanatiska krafter ifrågasätter Atreides styre av imperiet och mer än ekonomisk katastrof hotar.');